    }

    /// Whether `contents[anchor]` is still the entry `anchorBytes` was taken from.
    func anchorHolds(in contents: [Content], anchor: Int, anchorBytes: Data?) -> Bool {
        guard let anchorBytes, contents.indices.contains(anchor) else { return false }
        return Self.anchorBytes(of: contents[anchor]) == anchorBytes
    }

    /// The bytes an anchor is validated against: sorted keys, so equal entries are equal bytes.
    /// Each `inlineData` is stood in for by its MIME type and encoded length, so a screenshot is
    /// not re-encoded on every round; role, text and every other part still count. The accepted
    /// limit: an entry identical except for an image of the same type and length matches. Getting
    /// one at the anchor mid-turn takes the UI removing the turn's entry and re-adding that.
    static func anchorBytes(of content: Content) -> Data? {
        var stripped = content
        for i in stripped.parts.indices {
            if let image = stripped.parts[i].inlineData {
                stripped.parts[i].inlineData = InlineData(mimeType: image.mimeType, data: "\(image.data.utf8.count)")
            }
        }
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.sortedKeys]
        return try? encoder.encode(stripped)
    }
}

/// One turn's block and where it goes. A turn sends two lists: round one sends the history the
/// PreCompress hook returned (`.initial`), and every later request re-reads AppState's own list
/// (`.state`), which the hook never touched. Each gets its own anchor, both taken once at the start
/// of the turn; the bytes come from AppState's entry, the one the turn appended.
struct TurnRequest: Sendable {
    enum HistoryList: Sendable { case initial, state }

    let context: TurnContext
    let stateAnchor: Int?
    let initialAnchor: Int?
    let anchorBytes: Data?
    private(set) var dropReported = false

    init(context: TurnContext, stateHistory: [Content], initialHistory: [Content]) {
        self.context = context
        let stateAnchor = stateHistory.lastIndex { $0.role == "user" }
        self.stateAnchor = stateAnchor
        initialAnchor = initialHistory.lastIndex { $0.role == "user" }
        // An empty context sends history as is (`contents(for:from:)`), so it needs no anchor.
        anchorBytes = context.isEmpty ? nil : stateAnchor.flatMap { TurnContext.anchorBytes(of: stateHistory[$0]) }
    }

    /// The request copy of `history`, and whether this is the first call of the turn to find the
    /// anchor broken (so the caller reports it once, not every round).
    mutating func contents(for history: [Content], from list: HistoryList) -> (contents: [Content], firstDrop: Bool) {
        guard !context.isEmpty else { return (history, false) }
        if let anchor = list == .initial ? initialAnchor : stateAnchor,
           context.anchorHolds(in: history, anchor: anchor, anchorBytes: anchorBytes) {
            return (context.applied(to: history, anchor: anchor, anchorBytes: anchorBytes), false)
        }

    /// What an error names. A Vertex failure says so and names the location, because "model not
    /// found" there usually means "not served in this location", which the API's wording hides.
    var providerLabel: String {
        switch self {
        case .direct: return "Anthropic"
        case .vertex(_, let location, _): return "Anthropic (Vertex AI, \(location))"
        }
    }

    /// A location is one DNS label (`global`, `us`, `us-east5`). Anything else is refused before
    /// a request is built, because the location becomes part of the HOST the bearer token is sent
    /// to: `foo.example.com/x?` would hand the ADC token to a non-Google host. Lowercase only, so
    /// `US-EAST5` is caught here rather than by a 404.
    static func isValidLocation(_ location: String) -> Bool {
        !location.isEmpty && location.count <= 63
            && location.allSatisfy { $0.isASCII && ($0.isLowercase || $0.isNumber || $0 == "-") }
    }

    /// The GCP project-id grammar: 6 to 30 characters, lowercase letters, digits and hyphens,
    /// starting with a letter and not ending with a hyphen; legacy domain-scoped ids carry a
    /// hostname prefix (`example.com:my-project`), which is labels joined by single dots. It is a
    /// path segment, so nothing else may reach the URL.
    static func isValidProject(_ project: String) -> Bool {
        let pattern = /^(?:[a-z0-9-]+(?:\.[a-z0-9-]+)*:)?[a-z][a-z0-9-]{4,28}[a-z0-9]$/
        return project.wholeMatch(of: pattern) != nil
    }

    /// The transport the Anthropic provider is configured for. `accessToken` is only called in
    /// Vertex mode, and only after the project has been checked: a missing project is a settings
    /// mistake, not a credentials one, and the sentence should say which.
    static func resolve(config: ConfigManager, accessToken: () async throws -> String) async throws -> AnthropicTransport {
        try await resolve(authMode: config.anthropicAuthMode, apiKey: config.anthropicAPIKey, baseURL: config.anthropicBaseURL,
                          project: config.anthropicVertexProject, location: config.effectiveVertexLocation, accessToken: accessToken)
    }

    /// The pure form, so a test can exercise it with literal values and never write the
    /// process-global Keychain store that `ConfigManager.anthropicAPIKey` is backed by.
    static func resolve(authMode: String, apiKey: String, baseURL: String, project: String, location: String,
                        accessToken: () async throws -> String) async throws -> AnthropicTransport {
        guard authMode == AnthropicAuthMode.vertex.rawValue else {
            return .direct(apiKey: apiKey, baseURL: baseURL)
        }
        let project = project.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !project.isEmpty else {
            throw APIError(message: "Anthropic on Vertex AI needs a Google Cloud project. Set it in Settings → LLM Providers → Vertex AI Project.")
        }
        guard isValidProject(project) else {
            throw APIError(message: "Vertex AI project \"\(project)\" is not a valid project id (lowercase letters, digits and hyphens).")
        }
        guard isValidLocation(location) else {
            throw APIError(message: "Vertex AI location \"\(location)\" is not valid: use global, us, eu, or a region such as us-east5.")
        }
        return .vertex(project: project, location: location, accessToken: try await accessToken())
    }
}

